740	// Context Management Functions
741	
742	// GetCurrentContext reads the current context name from .current-context
743	// Returns "default" if the file does not exist or is empty
744	func GetCurrentContext() (string, error) {
745		homeDir, err := os.UserHomeDir()
746		if err != nil {
747			return "", err
748		}
749	
750		contextFile := filepath.Join(homeDir, ".devdesk", ".current-context")
751	
752		// If the file does not exist, return "default"
753		if _, err := os.Stat(contextFile); os.IsNotExist(err) {
754			return "default", nil
755		}
756	
757		data, err := os.ReadFile(contextFile)
758		if err != nil {
759			return "", err
760		}
761	
762		context := strings.TrimSpace(string(data))
763		if context == "" {
764			return "default", nil
765		}
766	
767		return context, nil
768	}
769	
770	// CurrentContextName returns the current context, falling back to "default"
771	// when it cannot be read.
772	//
773	// Everything that needs the context name to scope something — Load, Save, the
774	// scan caches — wants a name and has no use for the error, since a home
775	// directory that cannot be resolved leaves nothing better to do than assume the
776	// default context. Three copies of that fallback existed before this.
777	func CurrentContextName() string {
778		ctx, err := GetCurrentContext()
779		if err != nil {
780			return "default"
781		}
782		return ctx
783	}
