785	// SetCurrentContext writes the context name to .current-context
786	func SetCurrentContext(name string) error {
787		if err := ValidateContextName(name); err != nil {
788			return err
789		}
790	
791		homeDir, err := os.UserHomeDir()
792		if err != nil {
793			return err
794		}
795	
796		contextFile := filepath.Join(homeDir, ".devdesk", ".current-context")
797	
798		// Ensure the directory exists
799		if err := EnsureConfigDir(); err != nil {
800			return err
801		}
802	
803		return os.WriteFile(contextFile, []byte(name), 0600)
804	}
805	
806	// ListContexts discovers the available contexts by listing config-*.yaml files
807	// Returns a slice of context names (without the "config-" prefix or ".yaml" suffix)
808	// Always includes "default" if config.yaml exists
809	func ListContexts() ([]string, error) {
810		homeDir, err := os.UserHomeDir()
811		if err != nil {
812			return nil, err
813		}
814	
815		configDir := filepath.Join(homeDir, ".devdesk")
816		contexts := []string{}
817	
818		// Check the default context
819		defaultPath := filepath.Join(configDir, "config.yaml")
820		if _, err := os.Stat(defaultPath); err == nil {
821			contexts = append(contexts, "default")
822		}
823	
824		// Glob for named contexts
825		pattern := filepath.Join(configDir, "config-*.yaml")
826		matches, err := filepath.Glob(pattern)
827		if err != nil {
828			return nil, err
829		}
830	
831		for _, match := range matches {
832			// Extract the name: config-{name}.yaml -> {name}
833			basename := filepath.Base(match)
834			name := strings.TrimPrefix(basename, "config-")
835			name = strings.TrimSuffix(name, ".yaml")
836			contexts = append(contexts, name)
837		}
838	
839		return contexts, nil
840	}
841	
842	// LoadContext loads the configuration for a specific context
843	// contextName = "default" -> config.yaml
844	// contextName = "dev" -> config-dev.yaml
845	func LoadContext(contextName string) (*Config, error) {
846		if err := ValidateContextName(contextName); err != nil {
847			return nil, err
848		}
849	
850		configPath, err := GetContextPath(contextName)
851		if err != nil {
852			return nil, err
853		}
854	
855		// Check whether the file exists
856		if _, err := os.Stat(configPath); os.IsNotExist(err) {
857			return nil, fmt.Errorf("context '%s' does not exist (no file at %s): %w", contextName, configPath, ErrContextNotFound)
858		}
859	
860		// Read and parse YAML
861		data, err := os.ReadFile(configPath)
862		if err != nil {
863			return nil, err
864		}
865	
866		var cfg Config
867		if err := yaml.Unmarshal(data, &cfg); err != nil {
868			return nil, fmt.Errorf("failed to parse context '%s': %w", contextName, err)
869		}
870	
871		// Apply the default values
872		if err := applyDefaults(&cfg); err != nil {
873			return nil, fmt.Errorf("invalid context '%s': %w", contextName, err)
874		}
875	
876		// Expand paths (tildes)
877		if home, err := os.UserHomeDir(); err == nil {
878			cfg.ExpandPaths(home)
879		}
880	
881		return &cfg, nil
882	}
883	
884	// ExpandPaths expands tildes (~) in configuration paths
885	func (c *Config) ExpandPaths(homeDir string) {
886		expand := func(path string) string {
887			if strings.HasPrefix(path, "~/") {
888				return filepath.Join(homeDir, path[2:])
889			}
890			return path
891		}
892	
893		c.App.LogFile = expand(c.App.LogFile)
894		c.App.WorkspacesDir = expand(c.App.WorkspacesDir)
895		c.Registry.CacheDir = expand(c.Registry.CacheDir)
896		c.Scan.CacheDir = expand(c.Scan.CacheDir)
897		for _, id := range ToolIDs() {
